class Solution {
public:
    int maxEqualAdjacentPairs(vector<int>& nums) {
        int base = 0, best = 0;
        map<pair<int, int>, int> edges;
        for (int i = 1; i < (int)nums.size(); ++i) {
            int x = nums[i - 1], y = nums[i];
            if (x == y) { ++base; continue; }
            if (x > y) swap(x, y);
            best = max(best, ++edges[{x, y}]);
        }
        return base + best;
    }
};
